use rand::prelude::*;
use std::io::{stdout, Write};
use std::time::{Duration, Instant};

// ============================================================================
// Constants
// ============================================================================

const BOARD_WIDTH: usize = 10;
const BOARD_HEIGHT: usize = 20;
const PREVIEW_SIZE: usize = 4;
const HOLD_PREVIEW_SIZE: usize = 4;

// ============================================================================
// Tetromino Definitions
// ============================================================================

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TetrominoType {
    I, O, T, S, Z, J, L,
}

impl TetrominoType {
    fn color(self) -> Color {
        match self {
            TetrominoType::I => Color::Cyan,
            TetrominoType::O => Color::Yellow,
            TetrominoType::T => Color::Magenta,
            TetrominoType::S => Color::Green,
            TetrominoType::Z => Color::Red,
            TetrominoType::J => Color::Blue,
            TetrominoType::L => Color::Rgb { r: 255, g: 165, b: 0 },
        }
    }

    fn character(self) -> char {
        '█'
    }

    fn initial_rotation_data(self) -> [[bool; 4]; 4] {
        match self {
            TetrominoType::I => [
                [false, false, false, false],
                [true, true, true, true],
                [false, false, false, false],
                [false, false, false, false],
            ],
            TetrominoType::O => [
                [false, false, false, false],
                [false, true, true, false],
                [false, true, true, false],
                [false, false, false, false],
            ],
            TetrominoType::T => [
                [false, false, false, false],
                [false, true, false, false],
                [true, true, true, false],
                [false, false, false, false],
            ],
            TetrominoType::S => [
                [false, false, false, false],
                [false, true, true, false],
                [true, true, false, false],
                [false, false, false, false],
            ],
            TetrominoType::Z => [
                [false, false, false, false],
                [true, true, false, false],
                [false, true, true, false],
                [false, false, false, false],
            ],
            TetrominoType::J => [
                [false, false, false, false],
                [true, false, false, false],
                [true, true, true, false],
                [false, false, false, false],
            ],
            TetrominoType::L => [
                [false, false, false, false],
                [false, false, true, false],
                [true, true, true, false],
                [false, false, false, false],
            ],
        }
    }
}

// ============================================================================
// SRS Rotation System
// ============================================================================

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum RotationState {
    North,
    East,
    South,
    West,
}

impl RotationState {
    fn rotate_cw(self) -> Self {
        match self {
            RotationState::North => RotationState::East,
            RotationState::East => RotationState::South,
            RotationState::South => RotationState::West,
            RotationState::West => RotationState::North,
        }
    }

    fn rotate_ccw(self) -> Self {
        match self {
            RotationState::North => RotationState::West,
            RotationState::West => RotationState::South,
            RotationState::South => RotationState::East,
            RotationState::East => RotationState::North,
        }
    }
}

// SRS wall kick data
// Format: [(test1_x, test1_y), (test2_x, test2_y), ...]
// For J, L, S, Z, T pieces
const WALL_KICK_DATA_JLSTZ: [[(i32, i32); 5]; 8] = [
    // North -> East
    [(0, 0), (-1, 0), (-1, 1), (0, -2), (-1, -2)],
    // East -> South
    [(0, 0), (1, 0), (1, -1), (0, 2), (1, 2)],
    // South -> West
    [(0, 0), (1, 0), (1, 1), (0, -2), (1, -2)],
    // West -> North
    [(0, 0), (-1, 0), (-1, -1), (0, 2), (-1, 2)],
    // East -> North (reverse)
    [(0, 0), (1, 0), (1, 1), (0, -2), (1, -2)],
    // South -> East (reverse)
    [(0, 0), (-1, 0), (-1, -1), (0, 2), (-1, 2)],
    // West -> South (reverse)
    [(0, 0), (-1, 0), (-1, 1), (0, -2), (-1, -2)],
    // North -> West (reverse)
    [(0, 0), (1, 0), (1, -1), (0, 2), (1, 2)],
];

// For I piece
const WALL_KICK_DATA_I: [[(i32, i32); 5]; 8] = [
    // North -> East
    [(0, 0), (-2, 0), (1, 0), (-2, -1), (1, 2)],
    // East -> South
    [(0, 0), (-1, 0), (2, 0), (-1, 2), (2, -1)],
    // South -> West
    [(0, 0), (2, 0), (-1, 0), (2, 1), (-1, -2)],
    // West -> North
    [(0, 0), (1, 0), (-2, 0), (1, -2), (-2, 1)],
    // East -> North (reverse)
    [(0, 0), (2, 0), (-1, 0), (2, 1), (-1, -2)],
    // South -> East (reverse)
    [(0, 0), (1, 0), (-2, 0), (1, -2), (-2, 1)],
    // West -> South (reverse)
    [(0, 0), (-2, 0), (1, 0), (-2, -1), (1, 2)],
    // North -> West (reverse)
    [(0, 0), (-1, 0), (2, 0), (-1, 2), (2, -1)],
];

// ============================================================================
// Piece Structure
// ============================================================================

#[derive(Clone, Debug)]
struct Piece {
    tetromino_type: TetrominoType,
    rotation: RotationState,
    x: i32,
    y: i32,
}

impl Piece {
    fn new(tetromino_type: TetrominoType) -> Self {
        Self {
            tetromino_type,
            rotation: RotationState::North,
            x: 3,
            y: 0,
        }
    }

    fn get_blocks(&self) -> Vec<(i32, i32)> {
        let rotation_data = self.get_rotation_data();
        let mut blocks = Vec::new();

        for row in 0..4 {
            for col in 0..4 {
                if rotation_data[row][col] {
                    blocks.push((self.x + col as i32, self.y + row as i32));
                }
            }
        }

        blocks
    }

    fn get_rotation_data(&self) -> [[bool; 4]; 4] {
        let mut data = self.tetromino_type.initial_rotation_data();

        match self.rotation {
            RotationState::North => {}
            RotationState::East => data = Self::rotate_matrix_cw(data),
            RotationState::South => data = Self::rotate_matrix_cw(Self::rotate_matrix_cw(data)),
            RotationState::West => data = Self::rotate_matrix_ccw(data),
        }

        data
    }

    fn rotate_matrix_cw(matrix: [[bool; 4]; 4]) -> [[bool; 4]; 4] {
        let mut result = [[false; 4]; 4];
        for row in 0..4 {
            for col in 0..4 {
                result[col][3 - row] = matrix[row][col];
            }
        }
        result
    }

    fn rotate_matrix_ccw(matrix: [[bool; 4]; 4]) -> [[bool; 4]; 4] {
        let mut result = [[false; 4]; 4];
        for row in 0..4 {
            for col in 0..4 {
                result[3 - col][row] = matrix[row][col];
            }
        }
        result
    }

    fn rotate_cw(&mut self, board: &Board) -> bool {
        let old_rotation = self.rotation;
        self.rotation = self.rotation.rotate_cw();

        let kick_data = self.get_wall_kick_data(old_rotation, self.rotation);

        for (dx, dy) in kick_data.iter() {
            self.x += dx;
            self.y += dy;

            if !board.collides_with(self) {
                return true;
            }

            self.x -= dx;
            self.y -= dy;
        }

        self.rotation = old_rotation;
        false
    }

    fn rotate_ccw(&mut self, board: &Board) -> bool {
        let old_rotation = self.rotation;
        self.rotation = self.rotation.rotate_ccw();

        let kick_data = self.get_wall_kick_data(old_rotation, self.rotation);

        for (dx, dy) in kick_data.iter() {
            self.x += dx;
            self.y += dy;

            if !board.collides_with(self) {
                return true;
            }

            self.x -= dx;
            self.y -= dy;
        }

        self.rotation = old_rotation;
        false
    }

    fn get_wall_kick_data(&self, from: RotationState, to: RotationState) -> [(i32, i32); 5] {
        let kick_index = match (from, to) {
            (RotationState::North, RotationState::East) => 0,
            (RotationState::East, RotationState::South) => 1,
            (RotationState::South, RotationState::West) => 2,
            (RotationState::West, RotationState::North) => 3,
            (RotationState::East, RotationState::North) => 4,
            (RotationState::South, RotationState::East) => 5,
            (RotationState::West, RotationState::South) => 6,
            (RotationState::North, RotationState::West) => 7,
            _ => return [(0, 0); 5],
        };

        match self.tetromino_type {
            TetrominoType::I => WALL_KICK_DATA_I[kick_index],
            TetrominoType::O => [(0, 0); 5], // O piece doesn't kick
            _ => WALL_KICK_DATA_JLSTZ[kick_index],
        }
    }

    fn move_down(&mut self) {
        self.y += 1;
    }

    fn move_left(&mut self) {
        self.x -= 1;
    }

    fn move_right(&mut self) {
        self.x += 1;
    }

    fn hard_drop(&mut self, board: &Board) -> i32 {
        let mut drop_distance = 0;
        while !board.collides_with(self) {
            self.y += 1;
            drop_distance += 1;
        }
        self.y -= 1;
        drop_distance - 1
    }

    fn get_ghost_y(&self, board: &Board) -> i32 {
        let mut ghost_y = self.y;
        let mut ghost_piece = self.clone();

        while {
            ghost_piece.y = ghost_y;
            !board.collides_with(&ghost_piece)
        } {
            ghost_y += 1;
        }

        ghost_y - 1
    }
}

// ============================================================================
// Board Structure
// ============================================================================

#[derive(Clone, Debug)]
struct Board {
    grid: [[Option<TetrominoType>; BOARD_WIDTH]; BOARD_HEIGHT],
}

impl Board {
    fn new() -> Self {
        Self {
            grid: [[None; BOARD_WIDTH]; BOARD_HEIGHT],
        }
    }

    fn collides_with(&self, piece: &Piece) -> bool {
        for (x, y) in piece.get_blocks() {
            if x < 0 || x >= BOARD_WIDTH as i32 || y >= BOARD_HEIGHT as i32 {
                return true;
            }
            if y >= 0 && self.grid[y as usize][x as usize].is_some() {
                return true;
            }
        }
        false
    }

    fn lock_piece(&mut self, piece: &Piece) {
        for (x, y) in piece.get_blocks() {
            if y >= 0 && y < BOARD_HEIGHT as i32 && x >= 0 && x < BOARD_WIDTH as i32 {
                self.grid[y as usize][x as usize] = Some(piece.tetromino_type);
            }
        }
    }

    fn clear_lines(&mut self) -> Vec<usize> {
        let mut cleared = Vec::new();

        for row in 0..BOARD_HEIGHT {
            if self.grid[row].iter().all(|cell| cell.is_some()) {
                cleared.push(row);
            }
        }

        for row in cleared.iter().rev() {
            self.grid.remove(*row);
            self.grid.insert(0, [None; BOARD_WIDTH]);
        }

        cleared
    }

    fn is_game_over(&self, piece: &Piece) -> bool {
        self.collides_with(piece)
    }

    fn check_t_spin(&self, piece: &Piece, last_rotation_cw: bool) -> bool {
        if piece.tetromino_type != TetrominoType::T {
            return false;
        }

        // Check corners around T piece center
        let corners = [
            (piece.x, piece.y),           // top-left
            (piece.x + 1, piece.y),       // top-right
            (piece.x, piece.y + 1),       // bottom-left
            (piece.x + 1, piece.y + 1),   // bottom-right
        ];

        let mut filled_corners = 0;
        for (cx, cy) in corners.iter() {
            if *cx < 0 || *cx >= BOARD_WIDTH as i32 || *cy < 0 || *cy >= BOARD_HEIGHT as i32 {
                filled_corners += 1;
            } else if self.grid[cy as usize][cx as usize].is_some() {
                filled_corners += 1;
            }
        }

        // T-spin requires at least 3 corners filled
        if filled_corners < 3 {
            return false;
        }

        // Must have rotated recently (we track this in game state)
        true
    }
}

// ============================================================================
// Bag Randomizer (7-bag system)
// ============================================================================

struct BagRandomizer {
    bag: Vec<TetrominoType>,
    rng: StdRng,
}

impl BagRandomizer {
    fn new() -> Self {
        Self {
            bag: Vec::new(),
            rng: StdRng::from_entropy(),
        }
    }

    fn next(&mut self) -> TetrominoType {
        if self.bag.is_empty() {
            self.refill_bag();
        }
        self.bag.pop().unwrap()
    }

    fn refill_bag(&mut self) {
        let mut pieces = vec![
            TetrominoType::I,
            TetrominoType::O,
            TetrominoType::T,
            TetrominoType::S,
            TetrominoType::Z,
            TetrominoType::J,
            TetrominoType::L,
        ];
        pieces.shuffle(&mut self.rng);
        self.bag = pieces;
    }

    fn peek_next(&mut self) -> TetrominoType {
        if self.bag.is_empty() {
            self.refill_bag();
        }
        *self.bag.last().unwrap()
    }
}

// ============================================================================
// Game State
// ============================================================================

struct GameState {
    board: Board,
    current_piece: Piece,
    next_piece: TetrominoType,
    hold_piece: Option<TetrominoType>,
    can_hold: bool,
    randomizer: BagRandomizer,
    score: u32,
    lines_cleared: u32,
    level: u32,
    combo: i32,
    back_to_back: bool,
    last_rotation_cw: Option<bool>,
    game_over: bool,
    paused: bool,
}

impl GameState {
    fn new() -> Self {
        let mut randomizer = BagRandomizer::new();
        let current_piece = Piece::new(randomizer.next());
        let next_piece = randomizer.peek_next();

        Self {
            board: Board::new(),
            current_piece,
            next_piece,
            hold_piece: None,
            can_hold: true,
            randomizer,
            score: 0,
            lines_cleared: 0,
            level: 1,
            combo: -1,
            back_to_back: false,
            last_rotation_cw: None,
            game_over: false,
            paused: false,
        }
    }

    fn spawn_new_piece(&mut self) {
        let tetromino_type = self.next_piece;
        self.next_piece = self.randomizer.next();
        self.current_piece = Piece::new(tetromino_type);
        self.can_hold = true;
        self.last_rotation_cw = None;

        if self.board.is_game_over(&self.current_piece) {
            self.game_over = true;
        }
    }

    fn hold_current_piece(&mut self) {
        if !self.can_hold {
            return;
        }

        let current_type = self.current_piece.tetromino_type;

        if let Some(held) = self.hold_piece {
            self.current_piece = Piece::new(held);
            self.hold_piece = Some(current_type);
        } else {
            self.hold_piece = Some(current_type);
            self.spawn_new_piece();
        }

        self.can_hold = false;
    }

    fn move_left(&mut self) {
        self.current_piece.move_left();
        if self.board.collides_with(&self.current_piece) {
            self.current_piece.move_right();
        }
    }

    fn move_right(&mut self) {
        self.current_piece.move_right();
        if self.board.collides_with(&self.current_piece) {
            self.current_piece.move_left();
        }
    }

    fn move_down(&mut self) -> bool {
        self.current_piece.move_down();
        if self.board.collides_with(&self.current_piece) {
            self.current_piece.y -= 1;
            return false;
        }
        true
    }

    fn rotate_cw(&mut self) {
        if self.current_piece.rotate_cw(&self.board) {
            self.last_rotation_cw = Some(true);
        }
    }

    fn rotate_ccw(&mut self) {
        if self.current_piece.rotate_ccw(&self.board) {
            self.last_rotation_cw = Some(false);
        }
    }

    fn soft_drop(&mut self) {
        if self.move_down() {
            self.score += 1;
        }
    }

    fn hard_drop(&mut self) {
        let drop_distance = self.current_piece.hard_drop(&self.board);
        self.score += drop_distance * 2;
        self.lock_and_clear();
    }

    fn lock_and_clear(&mut self) {
        let t_spin = self.board.check_t_spin(&self.current_piece, self.last_rotation_cw.unwrap_or(false));
        let lines_cleared = self.board.clear_lines();
        let num_lines = lines_cleared.len();

        if num_lines > 0 {
            // Combo scoring
            if self.combo < 0 {
                self.combo = 0;
            } else {
                self.combo += 1;
            }

            // Back-to-back detection
            let is_b2b = (num_lines == 4) || (t_spin && num_lines > 0);

            // Calculate score
            let base_score = match num_lines {
                1 => 100,
                2 => 300,
                3 => 500,
                4 => 800,
                _ => 0,
            };

            let t_spin_bonus = if t_spin {
                match num_lines {
                    1 => 400,
                    2 => 800,
                    3 => 1200,
                    _ => 0,
                }
            } else {
                0
            };

            let combo_bonus = self.combo * 50;
            let b2b_bonus = if is_b2b && self.back_to_back { base_score / 2 } else { 0 };

            self.score += base_score + t_spin_bonus + combo_bonus + b2b_bonus + (self.level - 1) * 50;
            self.lines_cleared += num_lines as u32;
            self.back_to_back = is_b2b;

            // Level up every 10 lines
            self.level = self.lines_cleared / 10 + 1;
        } else {
            self.combo = -1;
        }

        self.spawn_new_piece();
    }

    fn get_drop_delay(&self) -> Duration {
        // Speed increases with level
        let base_delay = 1000u64;
        let delay_per_level = 50u64;
        let min_delay = 100u64;

        let delay = base_delay - (self.level - 1) * delay_per_level;
        Duration::from_millis(delay.max(min_delay))
    }
}

// ============================================================================
// Renderer
// ============================================================================

struct Renderer {
    stdout: stdout::Stdout,
}

impl Renderer {
    fn new() -> Self {
        Self {
            stdout: stdout(),
        }
    }

    fn clear(&mut self) {
        execute!(self.stdout, Clear(ClearType::All), MoveTo(0, 0)).unwrap();
    }

    fn draw_block(&mut self, x: usize, y: usize, color: Color) {
        execute!(
            self.stdout,
            MoveTo(x as u16, y as u16),
            SetForegroundColor(color),
            Print('█'),
            ResetColor
        ).unwrap();
    }

    fn draw_empty_block(&mut self, x: usize, y: usize) {
        execute!(
            self.stdout,
            MoveTo(x as u16, y as u16),
            SetForegroundColor(Color::DarkGrey),
            Print('·'),
            ResetColor
        ).unwrap();
    }

    fn draw_board(&mut self, board: &Board, current_piece: &Piece) {
        // Draw border
        for y in 0..=BOARD_HEIGHT {
            execute!(self.stdout, MoveTo(0, y as u16), Print('│')).unwrap();
            execute!(self.stdout, MoveTo((BOARD_WIDTH + 1) as u16, y as u16), Print('│')).unwrap();
        }
        for x in 0..=BOARD_WIDTH {
            execute!(self.stdout, MoveTo(x as u16, BOARD_HEIGHT as u16), Print('─')).unwrap();
        }
        execute!(self.stdout, MoveTo(0, 0), Print('┌')).unwrap();
        execute!(self.stdout, MoveTo((BOARD_WIDTH + 1) as u16, 0), Print('┐')).unwrap();
        execute!(self.stdout, MoveTo(0, BOARD_HEIGHT as u16), Print('└')).unwrap();
        execute!(self.stdout, MoveTo((BOARD_WIDTH + 1) as u16, BOARD_HEIGHT as u16), Print('┘')).unwrap();

        // Draw board cells
        for row in 0..BOARD_HEIGHT {
            for col in 0..BOARD_WIDTH {
                if let Some(tetromino_type) = board.grid[row][col] {
                    self.draw_block(col + 1, row, tetromino_type.color());
                } else {
                    self.draw_empty_block(col + 1, row);
                }
            }
        }

        // Draw ghost piece
        let ghost_y = current_piece.get_ghost_y(board);
        let mut ghost_piece = current_piece.clone();
        ghost_piece.y = ghost_y;

        for (x, y) in ghost_piece.get_blocks() {
            if y >= 0 && y < BOARD_HEIGHT as i32 && x >= 0 && x < BOARD_WIDTH as i32 {
                if board.grid[y as usize][x as usize].is_none() {
                    execute!(
                        self.stdout,
                        MoveTo((x + 1) as u16, y as u16),
                        SetForegroundColor(current_piece.tetromino_type.color().darken()),
                        Print('▒'),
                        ResetColor
                    ).unwrap();
                }
            }
        }

        // Draw current piece
        for (x, y) in current_piece.get_blocks() {
            if y >= 0 && y < BOARD_HEIGHT as i32 && x >= 0 && x < BOARD_WIDTH as i32 {
                self.draw_block((x + 1) as usize, y as usize, current_piece.tetromino_type.color());
            }
        }
    }

    fn draw_next_piece(&mut self, tetromino_type: TetrominoType) {
        let piece = Piece::new(tetromino_type);
        let rotation_data = piece.get_rotation_data();

        execute!(self.stdout, MoveTo(BOARD_WIDTH + 3, 1), Print("NEXT")).unwrap();

        for row in 0..PREVIEW_SIZE {
            for col in 0..PREVIEW_SIZE {
                let x = BOARD_WIDTH + 3 + col as usize;
                let y = 3 + row as usize;

                if rotation_data[row][col] {
                    self.draw_block(x, y, tetromino_type.color());
                } else {
                    execute!(self.stdout, MoveTo(x as u16, y as u16), Print(' '), ResetColor).unwrap();
                }
            }
        }
    }

    fn draw_hold_piece(&mut self, hold_piece: Option<TetrominoType>, can_hold: bool) {
        execute!(self.stdout, MoveTo(BOARD_WIDTH + 3, 8), Print("HOLD")).unwrap();

        if let Some(tetromino_type) = hold_piece {
            let piece = Piece::new(tetromino_type);
            let rotation_data = piece.get_rotation_data();

            for row in 0..HOLD_PREVIEW_SIZE {
                for col in 0..HOLD_PREVIEW_SIZE {
                    let x = BOARD_WIDTH + 3 + col as usize;
                    let y = 10 + row as usize;

                    if rotation_data[row][col] {
                        if can_hold {
                            self.draw_block(x, y, tetromino_type.color());
                        } else {
                            execute!(
                                self.stdout,
                                MoveTo(x as u16, y as u16),
                                SetForegroundColor(Color::DarkGrey),
                                Print('█'),
                                ResetColor
                            ).unwrap();
                        }
                    } else {
                        execute!(self.stdout, MoveTo(x as u16, y as u16), Print(' '), ResetColor).unwrap();
                    }
                }
            }
        }
    }

    fn draw_stats(&mut self, score: u32, lines: u32, level: u32, combo: i32) {
        let stats_y = 16;
        let x = BOARD_WIDTH + 3;

        execute!(self.stdout, MoveTo(x as u16, stats_y as u16), Print("SCORE"), ResetColor).unwrap();
        execute!(self.stdout, MoveTo(x as u16, (stats_y + 1) as u16), Print(format!("{:06}", score)), ResetColor).unwrap();

        execute!(self.stdout, MoveTo(x as u16, (stats_y + 3) as u16), Print("LINES"), ResetColor).unwrap();
        execute!(self.stdout, MoveTo(x as u16, (stats_y + 4) as u16), Print(format!("{}", lines)), ResetColor).unwrap();

        execute!(self.stdout, MoveTo(x as u16, (stats_y + 6) as u16), Print("LEVEL"), ResetColor).unwrap();
        execute!(self.stdout, MoveTo(x as u16, (stats_y + 7) as u16), Print(format!("{}", level)), ResetColor).unwrap();

        if combo > 0 {
            execute!(
                self.stdout,
                MoveTo(x as u16, (stats_y + 9) as u16),
                SetForegroundColor(Color::Rgb { r: 255, g: 215, b: 0 }),
                Print(format!("{} COMBO!", combo)),
                ResetColor
            ).unwrap();
        }
    }

    fn draw_controls(&mut self) {
        let y = BOARD_HEIGHT + 2;
        execute!(self.stdout, MoveTo(0, y as u16), Print("Controls:")).unwrap();
        execute!(self.stdout, MoveTo(0, (y + 1) as u16), Print("←/→ : Move")).unwrap();
        execute!(self.stdout, MoveTo(0, (y + 2) as u16), Print("↑    : Rotate CW")).unwrap();
        execute!(self.stdout, MoveTo(0, (y + 3) as u16), Print("Z    : Rotate CCW")).unwrap();
        execute!(self.stdout, MoveTo(0, (y + 4) as u16), Print("↓    : Soft Drop")).unwrap();
        execute!(self.stdout, MoveTo(0, (y + 5) as u16), Print("Space: Hard Drop")).unwrap();
        execute!(self.stdout, MoveTo(0, (y + 6) as u16), Print("C    : Hold")).unwrap();
        execute!(self.stdout, MoveTo(0, (y + 7) as u16), Print("P    : Pause")).unwrap();
        execute!(self.stdout, MoveTo(0, (y + 8) as u16), Print("Q    : Quit")).unwrap();
    }

    fn draw_game_over(&mut self, score: u32) {
        let msg = "GAME OVER";
        let score_msg = format!("Final Score: {}", score);
        let restart_msg = "Press R to Restart or Q to Quit";

        let center_x = BOARD_WIDTH / 2;
        let center_y = BOARD_HEIGHT / 2;

        execute!(
            self.stdout,
            MoveTo(center_x as u16 - 4, center_y as u16),
            SetForegroundColor(Color::Red),
            Print(msg),
            ResetColor
        ).unwrap();

        execute!(
            self.stdout,
            MoveTo(center_x as u16 - 6, (center_y + 2) as u16),
            Print(score_msg)
        ).unwrap();

        execute!(
            self.stdout,
            MoveTo(center_x as u16 - 15, (center_y + 4) as u16),
            Print(restart_msg)
        ).unwrap();
    }

    fn draw_paused(&mut self) {
        let msg = "PAUSED";
        let center_x = BOARD_WIDTH / 2;
        let center_y = BOARD_HEIGHT / 2;

        execute!(
            self.stdout,
            MoveTo(center_x as u16 - 3, center_y as u16),
            SetForegroundColor(Color::Yellow),
            Print(msg),
            ResetColor
        ).unwrap();
    }

    fn render(&mut self, state: &GameState) {
        self.clear();
        self.draw_board(&state.board, &state.current_piece);
        self.draw_next_piece(state.next_piece);
        self.draw_hold_piece(state.hold_piece, state.can_hold);
        self.draw_stats(state.score, state.lines_cleared, state.level, state.combo);
        self.draw_controls();

        if state.game_over {
            self.draw_game_over(state.score);
        } else if state.paused {
            self.draw_paused();
        }

        self.stdout.flush().unwrap();
    }
}

// ============================================================================
// Main Game Loop
// ============================================================================

fn run_game() {
    let mut state = GameState::new();
    let mut renderer = Renderer::new();

    // Setup terminal
    enable_raw_mode().unwrap();
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen, Hide).unwrap();

    let mut last_drop = Instant::now();
    let mut running = true;

    while running {
        // Handle input
        if poll(Duration::from_millis(10)).unwrap() {
            if let Ok(Event::Key(key_event)) = read() {
                if key_event.kind == KeyEventKind::Press {
                    match key_event.code {
                        KeyCode::Char('q') | KeyCode::Char('Q') => {
                            running = false;
                        }
                        KeyCode::Char('p') | KeyCode::Char('P') => {
                            if !state.game_over {
                                state.paused = !state.paused;
                            }
                        }
                        KeyCode::Char('r') | KeyCode::Char('R') => {
                            if state.game_over {
                                state = GameState::new();
                            }
                        }
                        _ if !state.paused && !state.game_over => {
                            match key_event.code {
                                KeyCode::Left => state.move_left(),
                                KeyCode::Right => state.move_right(),
                                KeyCode::Down => state.soft_drop(),
                                KeyCode::Up => state.rotate_cw(),
                                KeyCode::Char('z') | KeyCode::Char('Z') => state.rotate_ccw(),
                                KeyCode::Char(' ') => state.hard_drop(),
                                KeyCode::Char('c') | KeyCode::Char('C') => state.hold_current_piece(),
                                _ => {}
                            }
                        }
                        _ => {}
                    }
                }
            }
        }

        // Auto drop
        if !state.paused && !state.game_over {
            let drop_delay = state.get_drop_delay();

            if last_drop.elapsed() >= drop_delay {
                if !state.move_down() {
                    state.lock_and_clear();
                }
                last_drop = Instant::now();
            }
        }

        renderer.render(&state);

        std::thread::sleep(Duration::from_millis(16)); // ~60 FPS
    }

    // Cleanup terminal
    disable_raw_mode().unwrap();
    execute!(stdout, Show, LeaveAlternateScreen).unwrap();
}

fn main() {
    run_game();
}
"}

{"content":"use crossterm::{
